.header("location");
String(res).replace(/result.*searchid/,
"/e/search/result/index.php?page={{page-1}}&searchid")

ruleBookInfo.init:
@js:
$ = (_) => java.getString(_);
({
    n: $("[property$=title]@content"),
    a: $("[property$=author]@content"),
    k: $("[property~=category|status|update_time]@content"),
    w: $("text.字数@text\#\#字数[：:]"),
    l: $("id.info@tag.p.3@a@text"),
    i: $("[property$=description]@content"),
    c: $("[property$=image]@content"),
    t: $("text.目录@href"),
    d: $("text.下载@href")
});

