@js:
var url=source.key,
html=java.ajax(url);
token=org.jsoup.Jsoup.parse(html)
.select('input[name=_token]')
.attr('value');
body=`_token=${token}<,&page=${page}>&keyword=`+key;
var so=url+"/search,"
var post={
  "body": String(body),
  "method": "POST"
};
so+JSON.stringify(post)

